import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.D7WGirly.js";const p=JSON.parse('{"title":"Integrations — Troubleshooting & FAQs","description":"","frontmatter":{},"headers":[],"relativePath":"integrations-04-troubleshooting-and-faqs.md","filePath":"integrations-04-troubleshooting-and-faqs.md"}'),i={name:"integrations-04-troubleshooting-and-faqs.md"};function s(r,e,l,h,u,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="integrations-—-troubleshooting-faqs" tabindex="-1">Integrations — Troubleshooting &amp; FAQs <a class="header-anchor" href="#integrations-—-troubleshooting-faqs" aria-label="Permalink to &quot;Integrations — Troubleshooting &amp; FAQs&quot;">​</a></h1><p><em>Common connection issues, sync problems, and answers to frequent questions</em></p><hr><h2 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h2><h3 id="who-can-connect-and-manage-integrations" tabindex="-1">Who can connect and manage integrations? <a class="header-anchor" href="#who-can-connect-and-manage-integrations" aria-label="Permalink to &quot;Who can connect and manage integrations?&quot;">​</a></h3><p>Any workspace member can connect and configure integrations — it is not restricted to admins.</p><h3 id="which-integrations-are-currently-live" tabindex="-1">Which integrations are currently live? <a class="header-anchor" href="#which-integrations-are-currently-live" aria-label="Permalink to &quot;Which integrations are currently live?&quot;">​</a></h3><p>Four integrations are live: Fireflies, Gong, JIRA, and the Lodestone REST API (via API keys). Fireflies and Gong both support configurable auto-sync.</p><h3 id="does-the-jira-integration-support-jira-server" tabindex="-1">Does the JIRA integration support JIRA Server? <a class="header-anchor" href="#does-the-jira-integration-support-jira-server" aria-label="Permalink to &quot;Does the JIRA integration support JIRA Server?&quot;">​</a></h3><p>No. The JIRA integration currently supports JIRA Cloud only. JIRA Server is not supported.</p><h3 id="can-i-connect-multiple-jira-projects" tabindex="-1">Can I connect multiple JIRA projects? <a class="header-anchor" href="#can-i-connect-multiple-jira-projects" aria-label="Permalink to &quot;Can I connect multiple JIRA projects?&quot;">​</a></h3><p>Yes. A workspace can connect to multiple JIRA projects, each with its own sync configuration and status mapping.</p><h3 id="do-fireflies-and-gong-sync-any-data-back-to-those-platforms" tabindex="-1">Do Fireflies and Gong sync any data back to those platforms? <a class="header-anchor" href="#do-fireflies-and-gong-sync-any-data-back-to-those-platforms" aria-label="Permalink to &quot;Do Fireflies and Gong sync any data back to those platforms?&quot;">​</a></h3><p>No. Both are discovery-only integrations — they bring transcripts into Lodestone&#39;s Extracts module. Nothing flows back to Fireflies or Gong from Lodestone.</p><h3 id="can-i-manually-link-an-existing-jira-issue-to-a-lodestone-feature" tabindex="-1">Can I manually link an existing JIRA issue to a Lodestone Feature? <a class="header-anchor" href="#can-i-manually-link-an-existing-jira-issue-to-a-lodestone-feature" aria-label="Permalink to &quot;Can I manually link an existing JIRA issue to a Lodestone Feature?&quot;">​</a></h3><p>Yes. From the Feature Detail page, you can link any existing JIRA issue to the Feature. Once linked, it syncs according to your configured sync behavior.</p><h3 id="can-i-unlink-a-feature-from-a-jira-issue" tabindex="-1">Can I unlink a Feature from a JIRA issue? <a class="header-anchor" href="#can-i-unlink-a-feature-from-a-jira-issue" aria-label="Permalink to &quot;Can I unlink a Feature from a JIRA issue?&quot;">​</a></h3><p>Yes. Unlinking from the Feature Detail page stops future sync between the two objects but does not delete either. Both remain in their respective systems.</p><h3 id="what-happens-to-my-data-if-i-disconnect-an-integration" tabindex="-1">What happens to my data if I disconnect an integration? <a class="header-anchor" href="#what-happens-to-my-data-if-i-disconnect-an-integration" aria-label="Permalink to &quot;What happens to my data if I disconnect an integration?&quot;">​</a></h3><p>Disconnecting stops future syncing but preserves all existing data in Lodestone. Features, status history, and any previously imported transcripts are not removed.</p><h3 id="should-i-use-automatic-sync-webhooks-or-both-for-jira" tabindex="-1">Should I use Automatic Sync, Webhooks, or both for JIRA? <a class="header-anchor" href="#should-i-use-automatic-sync-webhooks-or-both-for-jira" aria-label="Permalink to &quot;Should I use Automatic Sync, Webhooks, or both for JIRA?&quot;">​</a></h3><p>Most teams should use both. Webhooks provide real-time sync; Automatic Sync acts as a safety net for any webhook events that are missed. Running both gives you real-time accuracy with built-in redundancy.</p><h3 id="what-jira-object-level-should-i-map-lodestone-features-to" tabindex="-1">What JIRA object level should I map Lodestone Features to? <a class="header-anchor" href="#what-jira-object-level-should-i-map-lodestone-features-to" aria-label="Permalink to &quot;What JIRA object level should I map Lodestone Features to?&quot;">​</a></h3><p>It depends on how your team structures JIRA. Epic and Story are the most common choices. Use Epic if each Feature represents a large initiative with multiple delivery tasks beneath it; use Story if Features map more directly to individual user-facing capabilities.</p><h3 id="will-changing-the-status-mapping-affect-existing-features" tabindex="-1">Will changing the status mapping affect existing Features? <a class="header-anchor" href="#will-changing-the-status-mapping-affect-existing-features" aria-label="Permalink to &quot;Will changing the status mapping affect existing Features?&quot;">​</a></h3><p>Status mapping changes apply to future sync events — they don&#39;t retroactively update Features that have already been synced. If a Feature is stuck at an incorrect status due to a previous mapping error, update it manually after correcting the mapping.</p><hr><h2 id="common-issues" tabindex="-1">Common Issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to &quot;Common Issues&quot;">​</a></h2><h3 id="jira-features-aren-t-syncing-to-lodestone" tabindex="-1">JIRA features aren&#39;t syncing to Lodestone <a class="header-anchor" href="#jira-features-aren-t-syncing-to-lodestone" aria-label="Permalink to &quot;JIRA features aren&#39;t syncing to Lodestone&quot;">​</a></h3><p>Check the following in order:</p><ol><li>Confirm the JIRA integration is connected in Settings &gt; Integrations</li><li>Check that Automatic Sync is enabled, or trigger a manual sync</li><li>Review the status mapping — if the JIRA status isn&#39;t mapped to a Lodestone stage, the update won&#39;t come through</li><li>If webhooks are configured, verify they&#39;re still active in your JIRA webhook settings</li><li>Confirm the Feature is linked to a JIRA issue — unlinked Features don&#39;t receive sync updates</li></ol><h3 id="a-feature-s-status-isn-t-updating-even-though-jira-shows-it-as-done" tabindex="-1">A Feature&#39;s status isn&#39;t updating even though JIRA shows it as done <a class="header-anchor" href="#a-feature-s-status-isn-t-updating-even-though-jira-shows-it-as-done" aria-label="Permalink to &quot;A Feature&#39;s status isn&#39;t updating even though JIRA shows it as done&quot;">​</a></h3><p>This is almost always a status mapping issue. Check Settings &gt; Integrations &gt; JIRA and confirm that the &quot;Done&quot; status (or whatever your JIRA workflow uses) is mapped to the Lodestone &quot;Completed&quot; stage. If your JIRA project uses a custom status name like &quot;Released&quot; or &quot;Closed&quot;, it needs to be explicitly mapped.</p><h3 id="i-m-seeing-duplicate-features-after-connecting-jira" tabindex="-1">I&#39;m seeing duplicate Features after connecting JIRA <a class="header-anchor" href="#i-m-seeing-duplicate-features-after-connecting-jira" aria-label="Permalink to &quot;I&#39;m seeing duplicate Features after connecting JIRA&quot;">​</a></h3><p>This can happen if automatic sync creates new Lodestone Features from JIRA issues that already exist as Features in Lodestone. To fix this, manually link the existing Lodestone Features to their corresponding JIRA issues and remove the duplicates. Going forward, use the manual link option for existing issues rather than relying on auto-creation.</p><h3 id="fireflies-or-gong-meetings-aren-t-appearing-in-the-extracts-import-list" tabindex="-1">Fireflies or Gong meetings aren&#39;t appearing in the Extracts import list <a class="header-anchor" href="#fireflies-or-gong-meetings-aren-t-appearing-in-the-extracts-import-list" aria-label="Permalink to &quot;Fireflies or Gong meetings aren&#39;t appearing in the Extracts import list&quot;">​</a></h3><p>For Fireflies:</p><ul><li>Confirm the Fireflies integration is connected in Settings &gt; Integrations</li><li>Check that the transcript has been generated in Fireflies — meetings without completed transcripts won&#39;t appear</li><li>Try disconnecting and reconnecting if the list appears stale</li></ul><p>For Gong:</p><ul><li>Confirm the Gong integration is connected in Settings &gt; Integrations</li><li>Check that the accounts you selected during setup include the user whose calls you&#39;re looking for</li><li>To change which accounts are included, update the Gong configuration in Settings &gt; Integrations</li></ul><h3 id="webhooks-stopped-working-after-a-jira-configuration-change" tabindex="-1">Webhooks stopped working after a JIRA configuration change <a class="header-anchor" href="#webhooks-stopped-working-after-a-jira-configuration-change" aria-label="Permalink to &quot;Webhooks stopped working after a JIRA configuration change&quot;">​</a></h3><p>JIRA webhooks can become inactive if the JIRA project configuration changes — for example, if the project is renamed, moved, or if webhook permissions are updated. Check your JIRA webhook settings to confirm the webhook is still active and pointing to the correct Lodestone endpoint. Reconnecting the integration from Settings &gt; Integrations often resolves this.</p><h3 id="status-updates-are-appearing-in-lodestone-with-a-delay" tabindex="-1">Status updates are appearing in Lodestone with a delay <a class="header-anchor" href="#status-updates-are-appearing-in-lodestone-with-a-delay" aria-label="Permalink to &quot;Status updates are appearing in Lodestone with a delay&quot;">​</a></h3><p>If webhooks are configured, updates should be near-instant. A delay usually means the webhook isn&#39;t firing correctly — check JIRA&#39;s webhook delivery log for errors. If automatic sync is your only method, updates will arrive on the next polling cycle (e.g. hourly). To reduce delay, enable webhooks alongside automatic sync.</p><hr><p><em>This is version 1 of the Integrations documentation, based on the Lodestone knowledge base from early 2025, updated with confirmed platform behavior.</em></p>',46)])])}const g=t(i,[["render",s]]);export{p as __pageData,g as default};
